// Sets up MSW (Mock Service Worker) in the browser with all our handlers.
// The worker file it registers is public/mockServiceWorker.js (generated by "npx msw init public").
import { setupWorker } from 'msw/browser'
import { handlers } from './handlers'
import { shareChanges } from './sync'

export const worker = setupWorker(...handlers)

// After every mocked answer, send what changed to this site's other windows (mocks/sync.ts).
worker.events.on('response:mocked', () => shareChanges())
